@dataclass
class AuditEntry:
    sequence:int; timestamp:str; user_id:str; username:str; action:str; resource:str
    resource_id:str; details:str; ip_address:str; severity:str; previous_hash:str; entry_hash:str=""
    def compute_hash(self):
        data=f"{self.sequence}|{self.timestamp}|{self.user_id}|{self.username}|{self.action}|{self.resource}|{self.resource_id}|{self.details}|{self.ip_address}|{self.severity}|{self.previous_hash}"
        return hashlib.sha256(data.encode()).hexdigest()
    def to_dict(self): return asdict(self)

class AuditLog:
    _instance=None; _lock=Lock()
    def __new__(cls):
        with cls._lock:
            if cls._instance is None: cls._instance=super().__new__(cls); cls._instance._init=False
            return cls._instance
