            e.entry_hash=e.compute_hash(); self._last_hash=e.entry_hash
            self._entries.append(e); self._persist(e); return e
    def log_login(self,uid,username,success,ip="127.0.0.1"): self.log(uid,username,"LOGIN" if success else "LOGIN_FAILED","auth","",f"success={success}",ip,"info" if success else "warning")
    def log_logout(self,uid,username): self.log(uid,username,"LOGOUT","auth","")
    def log_create(self,uid,username,resource,rid,details=""): self.log(uid,username,"CREATE",resource,rid,details)
    def log_update(self,uid,username,resource,rid,details=""): self.log(uid,username,"UPDATE",resource,rid,details)
    def log_delete(self,uid,username,resource,rid,details=""): self.log(uid,username,"DELETE",resource,rid,details,severity="warning")
    def log_compliance_violation(self,uid,username,vtype,details): self.log(uid,username,"COMPLIANCE_VIOLATION","legal",vtype,details,severity="critical")
    def log_schedule_generated(self,uid,username,sid,details): self.log(uid,username,"SCHEDULE_GENERATED","schedule",sid,details)
    def log_security_event(self,uid,username,event,details): self.log(uid,username,"SECURITY_EVENT","security",event,details,severity="critical")
    def verify_chain(self):
        if not self._entries: return {"valid":True,"total_entries":0,"broken_at":None}
        prev="GENESIS_BLOCK_"+"0"*50
        for i,e in enumerate(self._entries):
            if e.previous_hash!=prev: return {"valid":False,"total_entries":len(self._entries),"broken_at":i}
