    def get_entries(self,limit=100,offset=0,user_id=None,action=None,severity=None,since=None):
        r=self._entries
        if user_id: r=[e for e in r if e.user_id==user_id]
        if action: r=[e for e in r if e.action==action]
        if severity: r=[e for e in r if e.severity==severity]
        if since: r=[e for e in r if datetime.fromisoformat(e.timestamp)>=since]
        return r[offset:offset+limit]
    def get_stats(self):
        bs={}; ba={}
        for e in self._entries: bs[e.severity]=bs.get(e.severity,0)+1; ba[e.action]=ba.get(e.action,0)+1
        return {"total_entries":len(self._entries),"by_severity":bs,"by_action":ba,"chain_valid":self.verify_chain()["valid"],"last_entry":self._entries[-1].timestamp if self._entries else None}
