        with open(self._log_file,"a",encoding="utf-8") as f: f.write(json.dumps(entry.to_dict(),ensure_ascii=False)+"\\n")
    def _load_chain(self):
        if not self._log_file.exists(): return
        try:
            with open(self._log_file,"r",encoding="utf-8") as f:
                for line in f:
                    line=line.strip()
                    if not line: continue
                    d=json.loads(line); e=AuditEntry(**d)
                    self._entries.append(e); self._sequence=e.sequence; self._last_hash=e.entry_hash
        except: pass

_audit=None
def get_audit():
    global _audit
    if _audit is None: _audit=AuditLog()
    return _audit
